import{_ as e,o as t,c as i,a5 as l}from"./chunks/framework.bIR-4glx.js";const g=JSON.parse('{"title":"用 AI 学英语：从练习到真实交付","description":"用英语基线、真实材料、引导练习、四项能力反馈和延迟复测学习，而不是把英语能力外包给一个 AI 产品。","frontmatter":{"title":"用 AI 学英语：从练习到真实交付","description":"用英语基线、真实材料、引导练习、四项能力反馈和延迟复测学习，而不是把英语能力外包给一个 AI 产品。","updated":"2026-11-23T00:00:00.000Z","sources_checked":"2026-11-23T00:00:00.000Z","source_review_interval":30},"headers":[],"relativePath":"threads/part-1/7-ai.md","filePath":"threads/part-1/7-ai.md","lastUpdated":1795392000000}'),s={name:"threads/part-1/7-ai.md"};function n(r,a,p,h,o,d){return t(),i("div",null,[...a[0]||(a[0]=[l(`<h1 id="用-ai-学英语-从练习到真实交付" tabindex="-1">用 AI 学英语：从练习到真实交付 <a class="header-anchor" href="#用-ai-学英语-从练习到真实交付" aria-label="Permalink to &quot;用 AI 学英语：从练习到真实交付&quot;">​</a></h1><p>AI 可以缩短找材料、生成练习和获得初步反馈的时间，却不能替你完成回忆、听辨、发音动作、判断和真实沟通。本章只回答一个问题：<strong>如何把 AI 放进英语训练，而不是把英语能力外包给 AI？</strong></p><p>全站通用的“问题—基线—练习—交付—验证—复盘”见<a href="./../part-3/1-ai-learning">使用 AI 学习一切</a>。这里只保留英语训练的具体做法。</p><h2 id="本章速览" tabindex="-1">本章速览 <a class="header-anchor" href="#本章速览" aria-label="Permalink to &quot;本章速览&quot;">​</a></h2><ul><li>先写真实场景和完成标准，再决定 AI 可以介入的步骤；</li><li>四项能力分别保留无 AI 基线、反馈和延迟复测；</li><li>让 AI 提问、提示和生成平行练习，不替你完成关键回忆与表达；</li><li>把结果写回<a href="./../../templates/ai-learning-log">AI 学习记录</a>和<a href="./../../templates/90-day-cycle">九十日行动总表</a>。</li></ul><blockquote><p>本页产品功能上次核验于 <strong>2026-11-23</strong>。学习模式、项目空间、语音和写作工具会因地区、语言、设备、账号和套餐变化；使用前请重新打开官方页面核对。</p></blockquote><h2 id="先定义-会英语" tabindex="-1">先定义“会英语” <a class="header-anchor" href="#先定义-会英语" aria-label="Permalink to &quot;先定义“会英语”&quot;">​</a></h2><p>不要从每天背多少单词开始，先写一个真实任务：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>场景：我要在英文线上会议中介绍一个 AI 项目。</span></span>
<span class="line"><span>受众：三位不了解技术细节的海外同事。</span></span>
<span class="line"><span>完成标准：三分钟内说明问题、方案、风险和下一步；回答两个追问；发送一封 150 词以内的跟进邮件。</span></span>
<span class="line"><span>期限：2026-09-30。</span></span>
<span class="line"><span>证据：原始录音、文字稿、问题记录、邮件草稿和修订版。</span></span></code></pre></div><p>目标至少包含场景、受众、动作、完成标准、期限和证据位置。AI 可以帮助练习和检查，不能替你定义“完成”。</p><h2 id="一、先测基线-再让-ai-介入" tabindex="-1">一、先测基线，再让 AI 介入 <a class="header-anchor" href="#一、先测基线-再让-ai-介入" aria-label="Permalink to &quot;一、先测基线，再让 AI 介入&quot;">​</a></h2><p>第一次不要让 AI 翻译、改写或提示。在同一主题下完成四个 10–15 分钟任务：</p><ol><li><strong>听力</strong>：听一段 2–4 分钟的真实材料，写主旨、三个细节和一个不确定点；</li><li><strong>阅读</strong>：读一页材料，写五句摘要和一个反例；</li><li><strong>口语</strong>：连续说两分钟，保存原始录音；</li><li><strong>写作</strong>：写一封 120–180 词工作邮件，不查词、不让 AI 改写。</li></ol><p>按任务完成、可理解度、准确与范围、组织与流畅、修订与迁移五项各打 0–2 分。把样本、评分理由和错误证据写入<a href="./../../templates/english-diagnostic">英语能力诊断</a>。没有基线，就无法知道 AI 帮助的是能力，还是只把成品变漂亮。</p><h2 id="四项能力与证据卡" tabindex="-1">四项能力与证据卡 <a class="header-anchor" href="#四项能力与证据卡" aria-label="Permalink to &quot;四项能力与证据卡&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>AI 可以协助</th><th>关闭 AI 后保留的证据</th></tr></thead><tbody><tr><td>听力</td><td>给出一个线索、标记时间段、生成平行追问</td><td><a href="./../../templates/listening-audit">听力证据卡</a>中的首听、六层错误地图、支架阶梯、意义重构和延迟迁移</td></tr><tr><td>阅读</td><td>比较段落标记、追问证据位置、提出平行来源问题</td><td><a href="./../../templates/reading-evidence">阅读证据卡</a>中的首读、障碍地图、主张证据、技术事实和推断边界</td></tr><tr><td>口语</td><td>记录难以理解的片段、模拟追问</td><td><a href="./../../templates/speaking-evidence">口语证据卡</a>中的原始录音、听众复述和修复</td></tr><tr><td>写作</td><td>分层指出事实、结构、语言和语气问题</td><td><a href="./../../templates/writing-evidence">写作证据卡</a>中的初稿、四轮修订和读者反馈</td></tr></tbody></table><p>卡片不是额外作业，而是把一次训练变成可回看的样本。若只留下 AI 的批注，没有自己的首版和迁移任务，下一次无法判断能力是否真的变化。</p><p>语法是四项能力共用的结构层。AI 可以把原句与平行句并排、提出意义差异、生成变式，但反馈必须区分<strong>错误、歧义、语域选择与风格偏好</strong>，并说明置信度；学习者再用<a href="./../../templates/grammar-evidence">语法证据卡</a>保存自己的决定。模型给出更顺的句子，不等于原句必然错误。</p><h2 id="二、每次训练使用同一张任务卡" tabindex="-1">二、每次训练使用同一张任务卡 <a class="header-anchor" href="#二、每次训练使用同一张任务卡" aria-label="Permalink to &quot;二、每次训练使用同一张任务卡&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># English Task Card</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">日期：YYYY-MM-DD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">真实场景：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">动作：听懂 / 阅读 / 表达 / 写作 / 提问 / 修订</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">完成标准：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">材料与来源：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">无 AI 基线位置：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AI 可以做：提示 / 追问 / 纠错 / 生成平行题</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AI 不可以做：代答 / 整段改写 / 编造来源</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">输出位置：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">反馈证据：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">重复错误：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">下一项最小任务：</span></span></code></pre></div><p>训练结束只挑 1–2 个最影响沟通的错误，重新做一个平行任务。不要把十五条建议抄进错误库，却没有再次使用。</p><h2 id="三、词汇-从眼熟到在真实任务中调用" tabindex="-1">三、词汇：从眼熟到在真实任务中调用 <a class="header-anchor" href="#三、词汇-从眼熟到在真实任务中调用" aria-label="Permalink to &quot;三、词汇：从眼熟到在真实任务中调用&quot;">​</a></h2><p>每周从真实材料中选 5–8 个高价值词块，不追求孤立词量。先保存不查词的首遇，再为每个词块记录：当前义项、发音、词性、搭配、原句、自己的句子、一个相近表达和一次主动回忆。未知项先决定放过、推断、速查、主动学习还是专业核验。</p><p>AI 可以生成填空、改错和替换练习，但释义、搭配和例句要回到学习者词典或真实语料核对。四次接触可以这样安排：</p><ol><li>当天理解原句并朗读；</li><li>第二天闭卷回忆并造句；</li><li>一周内在口语或邮件里主动使用；</li><li>两周后在新场景中迁移。</li></ol><p>验收不是“收藏了多少”，而是能否在没有提示时正确使用，并让对方理解。</p><h2 id="四、听力-把-没听懂-拆开" tabindex="-1">四、听力：把“没听懂”拆开 <a class="header-anchor" href="#四、听力-把-没听懂-拆开" aria-label="Permalink to &quot;四、听力：把“没听懂”拆开&quot;">​</a></h2><p>第一次只写主旨和确定细节，不看字幕。第二次标记问题属于哪一类：</p><ul><li>词汇不认识；</li><li>认识单词但连读、弱读或重音没有听出；</li><li>句法关系没有解析；</li><li>背景知识不足；</li><li>语速、口音或注意力造成的暂时失败。</li></ul><p>让 AI 先指出一个最小线索，再回听 10–20 秒；不要直接给整段翻译。最后关闭字幕，用自己的话复述，并记录仍然不确定的部分。</p><p>每一遍要承担不同问题：先保存无字幕首听，再定位时间段和障碍层；只打开必要转写，关闭文字后重构主旨、关系和下一步；三到七天后用平行材料撤架复测。完整记录见<a href="./../../templates/listening-audit">听力证据卡</a>。AI 可以提供候选转写，不能替原始音频和可靠来源做最终裁决。</p><h2 id="五、口语与发音-以沟通结果为中心" tabindex="-1">五、口语与发音：以沟通结果为中心 <a class="header-anchor" href="#五、口语与发音-以沟通结果为中心" aria-label="Permalink to &quot;五、口语与发音：以沟通结果为中心&quot;">​</a></h2><p>一次 12 分钟训练：</p><ol><li>不看稿说明一个真实问题 2 分钟；</li><li>让 AI 只记录听不清、逻辑断裂和需要澄清的地方；</li><li>选择一个影响理解的发音或词块问题，做 5 次慢速重说；</li><li>回答一个没有预先准备的追问；</li><li>保存原始与复测录音。</li></ol><p>语音识别结果只是线索，不等于自然发音。最可靠的验收是可信的听者是否能一次理解、是否需要重复，以及你能否在新问题中继续表达。</p><p>先选择与真实受众相关的参考变体，再逐步加入其他英语变体；不要让模型把“听起来不同”自动改写成“错误”。使用<a href="./../../templates/speaking-evidence">口语证据卡</a>保存设备、听众熟悉度、识别错误、听众复述与互动修复，区分口音显著度、实际误解和理解成本。</p><h2 id="六、阅读-训练证据链-而不是收集摘要" tabindex="-1">六、阅读：训练证据链，而不是收集摘要 <a class="header-anchor" href="#六、阅读-训练证据链-而不是收集摘要" aria-label="Permalink to &quot;六、阅读：训练证据链，而不是收集摘要&quot;">​</a></h2><p>先独立标记作者的主张、证据、定义、例子和未知项，再让 AI 比较你的标记。要求它给出原文位置，不接受“文章大意是”。</p><p>关闭材料后回答：作者解决什么问题？哪个结论依赖哪条证据？有什么反例？如果把场景换成自己的工作，哪些部分仍成立？能回答这些问题，才算从阅读迁移到判断。</p><h2 id="七、写作-保留作者的手" tabindex="-1">七、写作：保留作者的手 <a class="header-anchor" href="#七、写作-保留作者的手" aria-label="Permalink to &quot;七、写作：保留作者的手&quot;">​</a></h2><p>第一版自己写。AI 只做分层反馈：事实与来源、任务完成、结构与逻辑、语言错误、语气和隐私风险。每次只修最影响目的的三处，并用自己的话解释为什么修改。</p><p>不要直接接受整段重写。保留原稿、AI 建议、最终稿和一封新的相似邮件，用于比较自己是否真的学会。若最终稿很好但无法解释关键改动，能力还没有稳定。</p><p>进一步使用<a href="./../../templates/writing-evidence">写作证据卡</a>记录事实与责任账本、翻译造成的意义变化、每条反馈的采纳/拒绝理由、自动工具版本、需要披露的范围和关闭工具后的平行任务。模型可以成为编辑助手，不能成为隐形作者；流畅不能替代来源、权限、署名和最终责任。</p><h2 id="八、选择工具-但不混淆功能" tabindex="-1">八、选择工具，但不混淆功能 <a class="header-anchor" href="#八、选择工具-但不混淆功能" aria-label="Permalink to &quot;八、选择工具，但不混淆功能&quot;">​</a></h2><table tabindex="0"><thead><tr><th>任务</th><th>可用能力</th><th>必须自己核对</th></tr></thead><tbody><tr><td>引导学习</td><td>学习模式、分层问答、测验</td><td>是否先让你作答，解释是否有来源</td></tr><tr><td>长期上下文</td><td>项目空间、允许上传的资料</td><td>权限、留存、记忆范围和导出</td></tr><tr><td>基于材料学习</td><td>文件问答、NotebookLM 等</td><td>原始页面、版权、隐私和是否越出材料</td></tr><tr><td>在线研究</td><td>带引用的搜索工具</td><td>打开原始页面，确认它真的支持结论</td></tr><tr><td>写作反馈</td><td>语言模型、写作工具</td><td>保留初稿，逐项理解修改</td></tr><tr><td>口语练习</td><td>语音对话</td><td>识别准确不等于自然发音，功能会变化</td></tr></tbody></table><p>这不是工具排名。先看资料是否允许上传、输出能否导出、错误能否复查，以及总成本是否值得。</p><p>平台记忆只是便利层。请把目标、样本、错误和下一步保存在<a href="./../../templates/learning-state">学习状态</a>或<a href="./../../templates/ai-learning-log">AI 学习记录</a>中。</p><h2 id="一次跨模态练习-从看懂到说清楚" tabindex="-1">一次跨模态练习：从看懂到说清楚 <a class="header-anchor" href="#一次跨模态练习-从看懂到说清楚" aria-label="Permalink to &quot;一次跨模态练习：从看懂到说清楚&quot;">​</a></h2><p>能同时使用图片、声音和文字，会增加练习的入口；入口增多以后，更需要知道自己在哪一步失去理解。下面是一项约二十分钟的教学设计，时间可按精力调整，效果需要自己验证。</p><ol><li><strong>自己先解释</strong>：选择一张有权使用、没有私人信息的英文图表或操作说明。不打开翻译，用英语说一分钟：它在讲什么，哪些数字或步骤最重要，哪里还不确定。保存原图与原始录音。</li><li><strong>分别检查两类错误</strong>：让 AI 指出图中支持或反驳你解释的位置，再对照录音检查转写。图中小数点被识别错、口音被转写错，先记为工具错误；确实误解了比较关系或说错了意思，再记为学习缺口。</li><li><strong>只修一个关键问题</strong>：选一个影响理解的句式或关系重新解释。要求 AI 提一个追问，自己先回答，再看反馈。不要用它润色后的整段文字替换自己的录音。</li><li><strong>换材料，撤掉帮助</strong>：三到七天后找一张结构相似、数字不同的图，不看旧稿再讲一次。必要时请真实听者复述你的意思；验收是对方能否理解、你能否澄清，以及关键事实是否正确。</li></ol><p>记录原图页码或区域、录音时间段、模型与日期。实时对话可以用于练习打断、澄清和轮流发言，但 AI 的赞许、识别成功或模拟流畅都不能直接证明真实交流能力。若没有可复查的录音或转写，只记录实际观察到的现象，不补写精确发音结论。</p><p>需要选择语音、视觉、检索或本地工具时，用 <a href="./../part-3/6-ai-trends-and-learning-roadmap">AI 趋势与学习路线</a>做一次小对照。功能越丰富，越要保留那份未经修饰的首版：它让进步有一个真实的起点。</p><h2 id="九、反馈协议与复测" tabindex="-1">九、反馈协议与复测 <a class="header-anchor" href="#九、反馈协议与复测" aria-label="Permalink to &quot;九、反馈协议与复测&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>先复述任务和完成标准，让我先提交尝试。</span></span>
<span class="line"><span>反馈分为：任务完成、可理解度、准确性、组织/流畅、词汇/语法、发音和迁移。</span></span>
<span class="line"><span>每类只选择最影响结果的 1–3 项，引用证据并标记置信度。</span></span>
<span class="line"><span>给一个最小提示和一个平行任务，不直接完成最终答案。</span></span></code></pre></div><p>第 30 天和第 12 周用相同主题、相似时长和相同限制复测。比较原始样本，而不是只比较 AI 改过的成品。真正的进步包括：更少依赖提示、更少重复错误、更快完成真实任务，以及在新场景中仍然能用。</p><p>每次复测后，至少把一项结果和下一变量写回<a href="./../../templates/90-day-cycle">九十日行动总表</a>，不要让训练停在聊天窗口里。</p><p>如果要比较 AI 介入前后和迁移后的完整变化，再用<a href="./../../templates/evidence-chain">证据链模板</a>保存四个时间点；九十日行动表负责安排周期，证据链负责解释结果。</p><p>准备岗位面试时，可以让 AI 根据公开岗位描述模拟招聘者、技术同事或客户，在你提交首版后提出陌生追问并分类错误。不要让它虚构经历、代写需要署名的申请或 take-home 说明，也不要在未获允许的真实面试里通过隐蔽提示代答。完整流程见<a href="./8-job-search-english">求职英语篇</a>与<a href="./../../templates/interview-evidence">求职英语证据卡</a>。</p><h2 id="十、7-天、30-天、12-周" tabindex="-1">十、7 天、30 天、12 周 <a class="header-anchor" href="#十、7-天、30-天、12-周" aria-label="Permalink to &quot;十、7 天、30 天、12 周&quot;">​</a></h2><h3 id="_7-天-建立一次闭环" tabindex="-1">7 天：建立一次闭环 <a class="header-anchor" href="#_7-天-建立一次闭环" aria-label="Permalink to &quot;7 天：建立一次闭环&quot;">​</a></h3><ul><li>保存四项基线中的至少一项；</li><li>用任务卡完成三次训练；</li><li>每次留下原始输出、反馈和一个平行任务；</li><li>记录一个最影响沟通的错误。</li></ul><h3 id="_30-天-建立错误库" tabindex="-1">30 天：建立错误库 <a class="header-anchor" href="#_30-天-建立错误库" aria-label="Permalink to &quot;30 天：建立错误库&quot;">​</a></h3><ul><li>完成至少四次同类真实任务；</li><li>按词汇、听辨、句法、组织、发音和迁移分类；</li><li>比较首稿与复测，不把 AI 改写当作能力增长；</li><li>删除不能改善结果的工具步骤。</li></ul><h3 id="_12-周-完成真实英语交付" tabindex="-1">12 周：完成真实英语交付 <a class="header-anchor" href="#_12-周-完成真实英语交付" aria-label="Permalink to &quot;12 周：完成真实英语交付&quot;">​</a></h3><ul><li>完成一次会议、演示、邮件、文档或跨文化协作任务；</li><li>保存录音、文字稿、反馈、修订和复测；</li><li>让真实受众确认是否理解、是否需要重复和下一步是否清楚；</li><li>把结果写回<a href="./../../templates/english-diagnostic">英语能力诊断</a>。</li></ul><h2 id="隐私、版权与官方来源" tabindex="-1">隐私、版权与官方来源 <a class="header-anchor" href="#隐私、版权与官方来源" aria-label="Permalink to &quot;隐私、版权与官方来源&quot;">​</a></h2><p>不要把客户、同事、学生、儿童、医疗记录、证件或未公开合同直接上传到未批准的工具。即使评论或网页公开，也要考虑授权、最少必要范围和删除期限。版权材料只在有权使用的范围内处理，保留来源和许可记录。</p><ul><li>OpenAI：<a href="https://openai.com/zh-Hans-CN/index/chatgpt-study-mode/" target="_blank" rel="noreferrer">学习模式简介</a>；<a href="https://help.openai.com/en/articles/10169521-projects" target="_blank" rel="noreferrer">Projects in ChatGPT</a></li><li>Google：<a href="https://support.google.com/gemini/answer/16448384" target="_blank" rel="noreferrer">在 Gemini 应用中使用学习工具</a>；<a href="https://support.google.com/gemini/answer/16275879" target="_blank" rel="noreferrer">创建测验、抽认卡等</a>；<a href="https://support.google.com/gemini/answer/15274899" target="_blank" rel="noreferrer">Gemini Live</a></li><li>Anthropic：<a href="https://support.claude.com/en/articles/9517075-what-are-projects" target="_blank" rel="noreferrer">What are projects?</a>（免费账号可建，最多五个项目；增强知识检索需付费套餐）</li><li>Google：<a href="https://notebooklm.google/" target="_blank" rel="noreferrer">NotebookLM</a></li><li>Perplexity：<a href="https://www.perplexity.ai/help-center/" target="_blank" rel="noreferrer">Help Center</a></li><li>DeepL：<a href="https://www.deepl.com/write" target="_blank" rel="noreferrer">DeepL Write</a></li></ul><p>这些页面只是可重新核验的产品入口，不是当前功能清单，也不构成工具排名或效果保证。产品入口的上次集中核验日期为 2026-11-23；使用前请重新核验功能、地区和套餐。</p><h2 id="结语-工具离场以后" tabindex="-1">结语：工具离场以后 <a class="header-anchor" href="#结语-工具离场以后" aria-label="Permalink to &quot;结语：工具离场以后&quot;">​</a></h2><p>AI 可以很快给出流畅的句子、耐心的解释和看似完整的答案。但英语能力不住在聊天窗口里。它住在工具关闭以后，你是否仍能听懂关键意思，是否能用自己的话说明，是否能在别人追问时继续思考。</p><p>让 AI 帮你看见盲点、生成练习和提供反馈，然后安排它离场。每次离场都像一次小小的退潮：被工具托住的部分会露出来，真正属于你的部分也会留下。如果意思随窗口一起消失，练习就还没有完成。</p><p>目标不是把自己训练成一个更像模型的人，而是在有限的词汇、真实的犹豫和必须承担的判断里，形成自己的声音。当工具离开，你仍然知道想说什么，也愿意为说出的话负责，AI 才是在放大能力，而不是替你占据它。</p>`,73)])])}const k=e(s,[["render",n]]);export{g as __pageData,k as default};
